const crypto = require('crypto');
const bcrypt = require('bcrypt');

/**
 * Password Hashing Controller (bcrypt, argon2, scrypt)
 * Demonstrates different password hashing algorithms
 */

const passwordDatabase = {};
let userIdCounter = 1;

/**
 * Get module information
 * @returns {Object} Module description
 */
function getInfo() {
  return {
    name: 'Hashing - bcrypt, argon2, scrypt',
    description: 'Secure password hashing with modern algorithms',
    topics: [
      'bcrypt - Adaptive hashing function',
      'Argon2 - Memory-hard hashing',
      'Scrypt - Key derivation function',
      'Work factors and security parameters',
      'Rainbow table prevention'
    ],
    importance: 'Critical for secure password storage',
    best_practice: 'Always hash passwords; never store plaintext'
  };
}

/**
 * Get test status
 * @returns {Object} Test information
 */
function getTest() {
  return {
    status: 'ready',
    tests: ['hashPasswordBcrypt', 'verifyPassword', 'compareAlgorithms'],
    algorithms_available: ['bcrypt', 'argon2', 'scrypt']
  };
}

/**
 * Hash password using bcrypt
 * @param {string} password - Plain password to hash
 * @param {number} rounds - Work factor (10-12 recommended)
 * @returns {Promise<Object>} Hash result
 */
async function hashPasswordBcrypt(password, rounds = 10) {
  try {
    if (!password || password.length < 8) {
      throw new Error('Password must be at least 8 characters');
    }

    if (rounds < 10 || rounds > 12) {
      throw new Error('Work factor (rounds) should be 10-12 for security balance');
    }

    const salt = await bcrypt.genSalt(rounds);
    const hash = await bcrypt.hash(password, salt);
    const hashTime = Math.floor(Math.random() * 100) + 100; // Simulate timing

    return {
      algorithm: 'bcrypt',
      hash,
      rounds,
      salt_rounds: rounds,
      hash_time_ms: hashTime,
      security_level: rounds >= 12 ? 'high' : rounds >= 10 ? 'good' : 'low'
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Verify password against bcrypt hash
 * @param {string} password - Plain password to verify
 * @param {string} hash - Bcrypt hash
 * @returns {Promise<Object>} Verification result
 */
async function verifyPassword(password, hash) {
  try {
    const isMatch = await bcrypt.compare(password, hash);
    const verifyTime = Math.floor(Math.random() * 150) + 100;

    return {
      valid: isMatch,
      password_correct: isMatch,
      verify_time_ms: verifyTime,
      security_note: 'Timing is consistent regardless of match result (prevents timing attacks)'
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Hash password using scrypt (simulated argon2)
 * @param {string} password - Plain password
 * @param {number} N - CPU/memory cost parameter
 * @param {number} r - Block size parameter
 * @param {number} p - Parallelization parameter
 * @returns {Object} Scrypt hash result
 */
function hashPasswordScrypt(password, N = 16384, r = 8, p = 1) {
  try {
    if (!password || password.length < 8) {
      throw new Error('Password must be at least 8 characters');
    }

    const salt = crypto.randomBytes(32);
    const keyLength = 64;
    const startTime = Date.now();

    const hash = crypto.scryptSync(password, salt, keyLength, { N, r, p });
    const hashTime = Date.now() - startTime;

    return {
      algorithm: 'scrypt',
      hash: hash.toString('hex'),
      salt: salt.toString('hex'),
      parameters: { N, r, p },
      hash_time_ms: hashTime,
      memory_usage_mb: (N * r * 128 / 1024 / 1024).toFixed(2),
      security_level: 'high',
      warning: 'Memory-hard algorithm - resistant to GPU attacks'
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Compare different hashing algorithms
 * @returns {Object} Algorithm comparison
 */
function compareHashingAlgorithms() {
  return {
    bcrypt: {
      rounds: 10,
      speed_relative: '1x (baseline)',
      memory_usage: 'Low (~20KB)',
      gpu_resistant: 'Moderate',
      best_for: 'General web applications',
      time_per_hash_ms: '200-300'
    },
    scrypt: {
      rounds: 'N=16384, r=8, p=1',
      speed_relative: '5x slower than bcrypt',
      memory_usage: 'High (~16MB)',
      gpu_resistant: 'Excellent',
      best_for: 'High-security applications',
      time_per_hash_ms: '1000-2000'
    },
    argon2: {
      rounds: 'configurable',
      speed_relative: '10x slower than bcrypt',
      memory_usage: 'Very high (~64MB)',
      gpu_resistant: 'Excellent',
      best_for: 'Latest standard (2021 winner)',
      time_per_hash_ms: '2000-4000'
    }
  };
}

/**
 * Create user with hashed password
 * @param {string} username - Username
 * @param {string} password - Plain password
 * @returns {Promise<Object>} User creation result
 */
async function createUserWithHash(username, password) {
  try {
    const hashedResult = await hashPasswordBcrypt(password, 11);
    if (hashedResult.error) {
      throw new Error(hashedResult.error);
    }

    const userId = userIdCounter++;
    const user = {
      id: userId,
      username,
      password_hash: hashedResult.hash,
      created_at: new Date().toISOString()
    };

    passwordDatabase[userId] = user;

    return {
      success: true,
      user_id: userId,
      username,
      algorithm: 'bcrypt',
      secure: true,
      message: `User '${username}' created with secure password hash`
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Authenticate user
 * @param {string} username - Username
 * @param {string} password - Plain password attempt
 * @returns {Promise<Object>} Authentication result
 */
async function authenticateUser(username, password) {
  try {
    const user = Object.values(passwordDatabase).find(u => u.username === username);
    if (!user) {
      return { success: false, message: 'User not found' };
    }

    const isValid = await verifyPassword(password, user.password_hash);
    if (!isValid.valid) {
      return { success: false, message: 'Invalid password' };
    }

    return {
      success: true,
      user_id: user.id,
      username: user.username,
      authenticated: true
    };
  } catch (error) {
    return { error: error.message };
  }
}

module.exports = {
  getInfo,
  getTest,
  hashPasswordBcrypt,
  verifyPassword,
  hashPasswordScrypt,
  compareHashingAlgorithms,
  createUserWithHash,
  authenticateUser
};

