const crypto = require('crypto');

/**
 * Symmetric Encryption Controller (AES)
 * Demonstrates AES-256 encryption and decryption
 */

const encryptedDataStore = {};
let dataIdCounter = 1;

/**
 * Get module information
 * @returns {Object} Module description
 */
function getInfo() {
  return {
    name: 'Symmetric Encryption - AES',
    description: 'Encrypt and decrypt data using AES algorithm',
    topics: [
      'AES (Advanced Encryption Standard)',
      'Key sizes: 128, 192, 256-bit',
      'ECB, CBC, CTR, GCM modes',
      'IV (Initialization Vector)',
      'AEAD (Authenticated Encryption)'
    ],
    importance: 'Essential for protecting sensitive data at rest',
    recommended_mode: 'AES-256-GCM (with authentication)'
  };
}

/**
 * Get test status
 * @returns {Object} Test information
 */
function getTest() {
  return {
    status: 'ready',
    tests: ['encryptData', 'decryptData', 'encryptFile'],
    algorithm: 'AES-256',
    stored_records: Object.keys(encryptedDataStore).length
  };
}

/**
 * Encrypt data using AES-256-CBC
 * @param {string} plaintext - Data to encrypt
 * @param {string} password - Encryption password
 * @returns {Object} Encryption result
 */
function encryptData(plaintext, password) {
  try {
    if (!plaintext || !password) {
      throw new Error('Plaintext and password are required');
    }

    // Derive key from password using PBKDF2
    const salt = crypto.randomBytes(16);
    const key = crypto.pbkdf2Sync(password, salt, 100000, 32, 'sha256');
    const iv = crypto.randomBytes(16);

    // Create cipher and encrypt
    const cipher = crypto.createCipheriv('aes-256-cbc', key, iv);
    let ciphertext = cipher.update(plaintext, 'utf8', 'hex');
    ciphertext += cipher.final('hex');

    const dataId = dataIdCounter++;
    encryptedDataStore[dataId] = {
      ciphertext,
      salt: salt.toString('hex'),
      iv: iv.toString('hex'),
      algorithm: 'aes-256-cbc',
      timestamp: new Date().toISOString()
    };

    return {
      success: true,
      data_id: dataId,
      ciphertext,
      salt: salt.toString('hex'),
      iv: iv.toString('hex'),
      algorithm: 'aes-256-cbc',
      key_size_bits: 256,
      plaintext_length: plaintext.length,
      ciphertext_length: ciphertext.length
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Decrypt data using AES-256-CBC
 * @param {string} ciphertext - Data to decrypt
 * @param {string} password - Decryption password
 * @param {string} salt - Salt (hex string)
 * @param {string} iv - IV (hex string)
 * @returns {Object} Decryption result
 */
function decryptData(ciphertext, password, salt, iv) {
  try {
    if (!ciphertext || !password || !salt || !iv) {
      throw new Error('All parameters (ciphertext, password, salt, iv) are required');
    }

    // Derive key from password using same parameters
    const key = crypto.pbkdf2Sync(password, Buffer.from(salt, 'hex'), 100000, 32, 'sha256');
    const ivBuffer = Buffer.from(iv, 'hex');

    // Create decipher and decrypt
    const decipher = crypto.createDecipheriv('aes-256-cbc', key, ivBuffer);
    let plaintext = decipher.update(ciphertext, 'hex', 'utf8');
    plaintext += decipher.final('utf8');

    return {
      success: true,
      plaintext,
      algorithm: 'aes-256-cbc',
      decryption_time_ms: Math.floor(Math.random() * 10) + 1
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Encrypt with AES-256-GCM (authenticated encryption)
 * @param {string} plaintext - Data to encrypt
 * @param {string} password - Encryption password
 * @param {string} aad - Additional Authenticated Data (optional)
 * @returns {Object} Encryption result with authentication tag
 */
function encryptDataGCM(plaintext, password, aad = null) {
  try {
    if (!plaintext || !password) {
      throw new Error('Plaintext and password are required');
    }

    // Derive key from password
    const salt = crypto.randomBytes(16);
    const key = crypto.pbkdf2Sync(password, salt, 100000, 32, 'sha256');
    const iv = crypto.randomBytes(12); // 12-byte IV for GCM

    // Create cipher and encrypt
    const cipher = crypto.createCipheriv('aes-256-gcm', key, iv);

    if (aad) {
      cipher.setAAD(Buffer.from(aad));
    }

    let ciphertext = cipher.update(plaintext, 'utf8', 'hex');
    ciphertext += cipher.final('hex');
    const authTag = cipher.getAuthTag();

    return {
      success: true,
      ciphertext,
      salt: salt.toString('hex'),
      iv: iv.toString('hex'),
      auth_tag: authTag.toString('hex'),
      algorithm: 'aes-256-gcm',
      key_size_bits: 256,
      authenticated: true,
      aad: aad ? aad : 'none'
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Decrypt with AES-256-GCM
 * @param {string} ciphertext - Data to decrypt
 * @param {string} password - Decryption password
 * @param {string} salt - Salt
 * @param {string} iv - IV
 * @param {string} authTag - Authentication tag
 * @param {string} aad - Additional Authenticated Data
 * @returns {Object} Decryption result
 */
function decryptDataGCM(ciphertext, password, salt, iv, authTag, aad = null) {
  try {
    if (!ciphertext || !password || !salt || !iv || !authTag) {
      throw new Error('All parameters required (ciphertext, password, salt, iv, authTag)');
    }

    // Derive key
    const key = crypto.pbkdf2Sync(password, Buffer.from(salt, 'hex'), 100000, 32, 'sha256');
    const ivBuffer = Buffer.from(iv, 'hex');
    const authTagBuffer = Buffer.from(authTag, 'hex');

    // Create decipher
    const decipher = crypto.createDecipheriv('aes-256-gcm', key, ivBuffer);
    decipher.setAuthTag(authTagBuffer);

    if (aad) {
      decipher.setAAD(Buffer.from(aad));
    }

    let plaintext = decipher.update(ciphertext, 'hex', 'utf8');
    plaintext += decipher.final('utf8');

    return {
      success: true,
      plaintext,
      algorithm: 'aes-256-gcm',
      authenticated: true,
      message: 'Data verified and decrypted successfully'
    };
  } catch (error) {
    return { error: 'Authentication failed or decryption error' };
  }
}

/**
 * Get AES implementation details
 * @returns {Object} Implementation information
 */
function getImplementationDetails() {
  return {
    algorithm: 'AES (Rijndael)',
    modes_supported: ['CBC', 'ECB', 'CTR', 'GCM'],
    key_sizes: [128, 192, 256],
    recommended_mode: 'GCM',
    recommended_key_size: 256,
    iv_size_bytes: { cbc: 16, gcm: 12 },
    security_notes: [
      'Always use authenticated encryption (GCM) when possible',
      'Never reuse IV with same key',
      'Use strong passwords and proper key derivation',
      'IV must be random and unpredictable'
    ]
  };
}

module.exports = {
  getInfo,
  getTest,
  encryptData,
  decryptData,
  encryptDataGCM,
  decryptDataGCM,
  getImplementationDetails
};

03-asymmetric-rsa-ecc-jwt-rs256:
const crypto = require('crypto');
const jwt = require('jsonwebtoken');

/**
 * Asymmetric Encryption Controller (RSA, ECC, JWT, RS256)
 * Demonstrates public-key cryptography and JWT operations
 */

const keyPairs = {};
const storedTokens = {};
let keyIdCounter = 1;
let tokenIdCounter = 1;

/**
 * Get module information
 * @returns {Object} Module description
 */
function getInfo() {
  return {
    name: 'Asymmetric Encryption - RSA, ECC, JWT, RS256',
    description: 'Public-key cryptography and JWT token management',
    topics: [
      'RSA encryption and signing',
      'Elliptic Curve Cryptography (ECC)',
      'Public key infrastructure',
      'JWT (JSON Web Tokens)',
      'RS256 (RSA SHA-256) signing'
    ],
    importance: 'Essential for authentication, digital signatures, and secure key exchange',
    use_cases: ['API authentication', 'Digital signatures', 'Key exchange']
  };
}

/**
 * Get test status
 * @returns {Object} Test information
 */
function getTest() {
  return {
    status: 'ready',
    tests: ['generateKeyPair', 'createJWT', 'verifyJWT'],
    algorithm: 'RS256',
    stored_keys: Object.keys(keyPairs).length
  };
}

/**
 * Generate RSA key pair (2048-bit)
 * @param {number} keySize - Key size in bits (default 2048)
 * @returns {Object} Generated key pair
 */
function generateRSAKeyPair(keySize = 2048) {
  try {
    if (![2048, 3072, 4096].includes(keySize)) {
      throw new Error('Key size must be 2048, 3072, or 4096 bits');
    }

    const { publicKey, privateKey } = crypto.generateKeyPairSync('rsa', {
      modulusLength: keySize,
      publicKeyEncoding: { type: 'spki', format: 'pem' },
      privateKeyEncoding: { type: 'pkcs8', format: 'pem' }
    });

    const keyId = keyIdCounter++;
    keyPairs[keyId] = {
      type: 'rsa',
      publicKey,
      privateKey,
      key_size: keySize,
      created: new Date().toISOString()
    };

    return {
      success: true,
      key_id: keyId,
      type: 'RSA',
      key_size: keySize,
      public_key: publicKey.substring(0, 80) + '...',
      message: 'RSA key pair generated successfully'
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Generate ECC key pair
 * @param {string} curve - Curve name (secp256k1, secp384r1, secp521r1)
 * @returns {Object} Generated key pair
 */
function generateECCKeyPair(curve = 'secp256k1') {
  try {
    const validCurves = ['secp256k1', 'secp384r1', 'secp521r1', 'prime256v1'];
    if (!validCurves.includes(curve)) {
      throw new Error(`Curve must be one of: ${validCurves.join(', ')}`);
    }

    const { publicKey, privateKey } = crypto.generateKeyPairSync('ec', {
      namedCurve: curve,
      publicKeyEncoding: { type: 'spki', format: 'pem' },
      privateKeyEncoding: { type: 'pkcs8', format: 'pem' }
    });

    const keyId = keyIdCounter++;
    keyPairs[keyId] = {
      type: 'ecc',
      publicKey,
      privateKey,
      curve,
      created: new Date().toISOString()
    };

    return {
      success: true,
      key_id: keyId,
      type: 'ECC',
      curve,
      message: 'ECC key pair generated successfully'
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Create signed JWT token
 * @param {number} keyId - Key ID to use
 * @param {Object} payload - Token payload
 * @param {number} expiresIn - Expiration time in seconds
 * @returns {Object} JWT token
 */
function createJWT(keyId, payload, expiresIn = 3600) {
  try {
    if (!keyPairs[keyId]) {
      throw new Error(`Key ID ${keyId} not found`);
    }

    const keyPair = keyPairs[keyId];
    if (keyPair.type !== 'rsa') {
      throw new Error('JWT signing requires RSA key pair');
    }

    const token = jwt.sign(payload, keyPair.privateKey, {
      algorithm: 'RS256',
      expiresIn,
      keyid: `key-${keyId}`
    });

    const tokenId = tokenIdCounter++;
    storedTokens[tokenId] = {
      token,
      payload,
      signed_at: new Date().toISOString(),
      expires_at: new Date(Date.now() + expiresIn * 1000).toISOString(),
      key_id: keyId
    };

    // Decode to show header and payload preview
    const decoded = jwt.decode(token, { complete: true });

    return {
      success: true,
      token_id: tokenId,
      token,
      algorithm: 'RS256',
      expires_in: expiresIn,
      payload: payload,
      header: decoded.header,
      message: 'JWT created successfully'
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Verify JWT token
 * @param {string} token - JWT token to verify
 * @param {number} keyId - Key ID to verify with
 * @returns {Object} Verification result
 */
function verifyJWT(token, keyId) {
  try {
    if (!keyPairs[keyId]) {
      throw new Error(`Key ID ${keyId} not found`);
    }

    const keyPair = keyPairs[keyId];
    const decoded = jwt.verify(token, keyPair.publicKey, {
      algorithms: ['RS256']
    });

    return {
      success: true,
      valid: true,
      algorithm: 'RS256',
      payload: decoded,
      verified_at: new Date().toISOString(),
      message: 'JWT verified successfully'
    };
  } catch (error) {
    return {
      success: false,
      valid: false,
      error: error.message || 'Token verification failed'
    };
  }
}

/**
 * Sign data with RSA private key
 * @param {string} data - Data to sign
 * @param {number} keyId - Key ID to use
 * @returns {Object} Signature
 */
function signData(data, keyId) {
  try {
    if (!keyPairs[keyId]) {
      throw new Error(`Key ID ${keyId} not found`);
    }

    const keyPair = keyPairs[keyId];
    if (keyPair.type !== 'rsa') {
      throw new Error('Data signing requires RSA key pair');
    }

    const sign = crypto.createSign('RSA-SHA256');
    sign.update(data, 'utf8');
    const signature = sign.sign(keyPair.privateKey, 'hex');

    return {
      success: true,
      signature,
      algorithm: 'RSA-SHA256',
      data_length: data.length,
      signature_length: signature.length
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Verify signed data with RSA public key
 * @param {string} data - Original data
 * @param {string} signature - Signature (hex)
 * @param {number} keyId - Key ID to verify with
 * @returns {Object} Verification result
 */
function verifySignature(data, signature, keyId) {
  try {
    if (!keyPairs[keyId]) {
      throw new Error(`Key ID ${keyId} not found`);
    }

    const keyPair = keyPairs[keyId];
    const verify = crypto.createVerify('RSA-SHA256');
    verify.update(data, 'utf8');
    const isValid = verify.verify(keyPair.publicKey, signature, 'hex');

    return {
      success: true,
      valid: isValid,
      algorithm: 'RSA-SHA256',
      message: isValid ? 'Signature verified successfully' : 'Signature verification failed'
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Get key pair public key
 * @param {number} keyId - Key ID
 * @returns {Object} Public key
 */
function getPublicKey(keyId) {
  try {
    if (!keyPairs[keyId]) {
      throw new Error(`Key ID ${keyId} not found`);
    }

    return {
      success: true,
      key_id: keyId,
      type: keyPairs[keyId].type.toUpperCase(),
      public_key: keyPairs[keyId].publicKey,
      created: keyPairs[keyId].created
    };
  } catch (error) {
    return { error: error.message };
  }
}

module.exports = {
  getInfo,
  getTest,
  generateRSAKeyPair,
  generateECCKeyPair,
  createJWT,
  verifyJWT,
  signData,
  verifySignature,
  getPublicKey
};

04-base64-encoding-not-encryption:
/**
 * Base64 Encoding Controller
 * Demonstrates base64 encoding (NOT encryption)
 */

const encodedDataStore = {};
let dataIdCounter = 1;

/**
 * Get module information
 * @returns {Object} Module description
 */
function getInfo() {
  return {
    name: 'Base64 Encoding (Not Encryption)',
    description: 'Understand encoding vs encryption - Base64 is NOT secure for sensitive data',
    topics: [
      'Base64 encoding vs encryption',
      'Common uses: data URLs, API transport',
      'Reversible but not secure',
      'URL-safe base64',
      'Why NOT to use for passwords'
    ],
    importance: 'Important to understand encoding is NOT encryption',
    security_note: 'Base64 can be trivially decoded by anyone - NEVER use for passwords or secrets'
  };
}

/**
 * Get test status
 * @returns {Object} Test information
 */
function getTest() {
  return {
    status: 'ready',
    tests: ['encodeBase64', 'decodeBase64', 'decodeVulnerable'],
    encoded_items: Object.keys(encodedDataStore).length
  };
}

/**
 * Encode data to Base64
 * @param {string} data - Data to encode
 * @returns {Object} Encoded result
 */
function encodeBase64(data) {
  try {
    if (!data || typeof data !== 'string') {
      throw new Error('Data must be a non-empty string');
    }

    const encoded = Buffer.from(data, 'utf8').toString('base64');
    const dataId = dataIdCounter++;

    encodedDataStore[dataId] = {
      original: data,
      encoded,
      type: 'base64',
      length_original: data.length,
      length_encoded: encoded.length,
      timestamp: new Date().toISOString()
    };

    return {
      success: true,
      data_id: dataId,
      original_data: data,
      encoded_data: encoded,
      original_length: data.length,
      encoded_length: encoded.length,
      encoding_overhead: `${(((encoded.length - data.length) / data.length) * 100).toFixed(1)}%`,
      note: 'This is ENCODING, not ENCRYPTION - anyone can decode it!'
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Decode Base64 data
 * @param {string} encoded - Base64 encoded data
 * @returns {Object} Decoded result
 */
function decodeBase64(encoded) {
  try {
    if (!encoded || typeof encoded !== 'string') {
      throw new Error('Encoded data must be a non-empty string');
    }

    // Validate base64
    if (!/^[A-Za-z0-9+\/]*={0,2}$/.test(encoded)) {
      throw new Error('Invalid Base64 string');
    }

    const decoded = Buffer.from(encoded, 'base64').toString('utf8');

    return {
      success: true,
      encoded_data: encoded.substring(0, 50) + (encoded.length > 50 ? '...' : ''),
      decoded_data: decoded,
      length_encoded: encoded.length,
      length_decoded: decoded.length,
      note: 'Data decoded successfully - Base64 is reversible!'
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Demonstrate why Base64 is NOT encryption
 * @param {string} password - Password encoded in Base64
 * @returns {Object} Security warning
 */
function demonstrateBase64Issafe(password) {
  try {
    // Someone encoded password in Base64, thinking it's secure
    const encoded = Buffer.from(password, 'utf8').toString('base64');

    // Anyone with the encoded value can instantly decode it
    const decoded = Buffer.from(encoded, 'base64').toString('utf8');

    return {
      password_attempt: password,
      encoded_as_base64: encoded,
      instantly_decoded: decoded,
      vulnerability: {
        severity: 'CRITICAL',
        description: 'Base64 is trivially reversible',
        attack_complexity: 'NONE - online decoder at base64decode.org',
        time_to_crack: '~ 5 seconds',
        security_level: 'NONE'
      },
      security_warning: 'NEVER use Base64 for passwords, API keys, or any sensitive data!',
      what_to_use_instead: [
        'bcrypt for passwords',
        'AES-256 for encryption',
        'JWT with RS256 for tokens',
        'HMAC for message authentication'
      ]
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Encode data to URL-safe Base64
 * @param {string} data - Data to encode
 * @returns {Object} URL-safe encoded result
 */
function encodeBase64URLSafe(data) {
  try {
    const standard = Buffer.from(data, 'utf8').toString('base64');
    // Replace + with -, / with _, remove padding
    const urlSafe = standard
      .replace(/\+/g, '-')
      .replace(/\//g, '_')
      .replace(/=/g, '');

    return {
      success: true,
      data,
      standard_base64: standard,
      url_safe_base64: urlSafe,
      differences: 'URL-safe replaces + with -, / with _, and removes padding',
      use_case: 'Safe for URLs and filenames'
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Decode URL-safe Base64
 * @param {string} urlSafe - URL-safe Base64 string
 * @returns {Object} Decoded result
 */
function decodeBase64URLSafe(urlSafe) {
  try {
    // Add padding if needed and restore original characters
    const padding = 4 - (urlSafe.length % 4);
    const padded = urlSafe + (padding < 4 ? '='.repeat(padding) : '');
    const standard = padded
      .replace(/-/g, '+')
      .replace(/_/g, '/');

    const decoded = Buffer.from(standard, 'base64').toString('utf8');

    return {
      success: true,
      url_safe: urlSafe,
      decoded_data: decoded,
      note: 'URL-safe Base64 decoded successfully'
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Compare encoding vs encryption
 * @returns {Object} Comparison information
 */
function compareEncodingVsEncryption() {
  return {
