const crypto = require('crypto');

/**
 * HMAC Message Authentication Controller
 * Demonstrates HMAC for message authentication and integrity verification
 */

const messageDatabase = {};
let messageIdCounter = 1;

/**
 * Get module information
 * @returns {Object} Module description
 */
function getInfo() {
  return {
    name: 'HMAC - Message Authentication',
    description: 'Generate and verify message authentication codes using HMAC',
    topics: [
      'HMAC (Hash-based Message Authentication Code)',
      'Message integrity verification',
      'Different hash algorithms: SHA256, SHA512, MD5',
      'HMAC vs signature vs hash',
      'API request signing'
    ],
    importance: 'Essential for verifying message authenticity and integrity',
    use_cases: ['API authentication', 'Webhook validation', 'Data integrity']
  };
}

/**
 * Get test status
 * @returns {Object} Test information
 */
function getTest() {
  return {
    status: 'ready',
    tests: ['generateHMAC', 'verifyHMAC', 'compareAlgorithms'],
    stored_messages: Object.keys(messageDatabase).length
  };
}

/**
 * Generate HMAC for a message
 * @param {string} message - Message to authenticate
 * @param {string} secret - Secret key
 * @param {string} algorithm - Hash algorithm (sha256, sha512, sha1, md5)
 * @returns {Object} HMAC result
 */
function generateHMAC(message, secret, algorithm = 'sha256') {
  try {
    if (!message || !secret) {
      throw new Error('Message and secret are required');
    }

    const validAlgorithms = ['sha256', 'sha512', 'sha1', 'md5'];
    if (!validAlgorithms.includes(algorithm)) {
      throw new Error(`Algorithm must be one of: ${validAlgorithms.join(', ')}`);
    }

    const hmac = crypto.createHmac(algorithm, secret);
    hmac.update(message, 'utf8');
    const digest = hmac.digest('hex');

    const messageId = messageIdCounter++;
    messageDatabase[messageId] = {
      message,
      secret: secret.substring(0, 8) + '***', // Hide secret
      algorithm,
      hmac: digest,
      timestamp: new Date().toISOString()
    };

    return {
      success: true,
      message_id: messageId,
      message,
      secret: secret.substring(0, 8) + '***',
      algorithm: algorithm.toUpperCase(),
      hmac: digest,
      hmac_length: digest.length,
      note: 'HMAC proves message authenticity AND integrity'
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Verify HMAC
 * @param {string} message - Original message
 * @param {string} secret - Secret key
 * @param {string} providedHMAC - HMAC to verify
 * @param {string} algorithm - Hash algorithm (default: sha256)
 * @returns {Object} Verification result
 */
function verifyHMAC(message, secret, providedHMAC, algorithm = 'sha256') {
  try {
    if (!message || !secret || !providedHMAC) {
      throw new Error('Message, secret, and HMAC are required');
    }

    const hmac = crypto.createHmac(algorithm, secret);
    hmac.update(message, 'utf8');
    const computedHMAC = hmac.digest('hex');

    // Constant-time comparison to prevent timing attacks
    const isValid = crypto.timingSafeEqual(
      Buffer.from(computedHMAC),
      Buffer.from(providedHMAC)
    );

    return {
      success: true,
      valid: isValid,
      verified: isValid,
      message: isValid ? 'HMAC verified successfully' : 'HMAC verification failed',
      provided_hmac: providedHMAC.substring(0, 16) + '...',
      computed_hmac: computedHMAC.substring(0, 16) + '...',
      algorithm: algorithm.toUpperCase(),
      timing_safe: true
    };
  } catch (error) {
    return { success: false, valid: false, error: error.message };
  }
}

/**
 * Sign API request with HMAC
 * @param {string} method - HTTP method
 * @param {string} path - Request path
 * @param {string} body - Request body
 * @param {string} apiSecret - API secret key
 * @returns {Object} Signed request
 */
function signAPIRequest(method, path, body, apiSecret) {
  try {
    if (!method || !path || !apiSecret) {
      throw new Error('Method, path, and API secret are required');
    }

    // Canonical string to sign
    const toSign = `${method}\n${path}\n${body || ''}`;
    const hmac = crypto.createHmac('sha256', apiSecret);
    hmac.update(toSign, 'utf8');
    const signature = hmac.digest('hex');

    return {
      success: true,
      method,
      path,
      signature,
      algorithm: 'HMAC-SHA256',
      header_name: 'X-Signature',
      header_value: signature,
      note: 'Include signature in request header for verification'
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Verify signed API request
 * @param {string} method - HTTP method
 * @param {string} path - Request path
 * @param {string} body - Request body
 * @param {string} signature - Provided signature
 * @param {string} apiSecret - API secret key
 * @returns {Object} Verification result
 */
function verifyAPISignature(method, path, body, signature, apiSecret) {
  try {
    const toSign = `${method}\n${path}\n${body || ''}`;
    const hmac = crypto.createHmac('sha256', apiSecret);
    hmac.update(toSign, 'utf8');
    const expectedSignature = hmac.digest('hex');

    const isValid = crypto.timingSafeEqual(
      Buffer.from(signature),
      Buffer.from(expectedSignature)
    );

    return {
      success: true,
      valid: isValid,
      authenticated: isValid,
      message: isValid ? 'API request signature verified' : 'Invalid signature'
    };
  } catch (error) {
    return { success: false, valid: false, error: 'Signature verification failed' };
  }
}

/**
 * Compare HMAC algorithms
 * @returns {Object} Algorithm comparison
 */
function compareAlgorithms() {
  return {
    sha256: {
      output_bits: 256,
      output_bytes: 32,
      speed: 'Fast',
      security: 'High',
      recommended: true,
      use_case: 'Standard choice'
    },
    sha512: {
      output_bits: 512,
      output_bytes: 64,
      speed: 'Very fast (optimized on 64-bit)',
      security: 'Very high',
      recommended: true,
      use_case: 'High-security applications'
    },
    sha1: {
      output_bits: 160,
      output_bytes: 20,
      speed: 'Fastest',
      security: 'Weak (deprecated)',
      recommended: false,
      use_case: 'Legacy only'
    },
    md5: {
      output_bits: 128,
      output_bytes: 16,
      speed: 'Fast',
      security: 'Broken (do not use)',
      recommended: false,
      use_case: 'Not suitable for HMAC'
    }
  };
}

module.exports = {
  getInfo,
  getTest,
  generateHMAC,
  verifyHMAC,
  signAPIRequest,
  verifyAPISignature,
  compareAlgorithms
};

