const keyManagementStore = {};
const encryptedStore = {};
let keyIdCounter = 1;
let dataIdCounter = 1;

// Master key (in real scenario, stored in secure HSM/KMS)
const masterKey = crypto.randomBytes(32);

/**
 * Get module information
 * @returns {Object} Module description
 */
function getInfo() {
  return {
    name: 'Envelope Encryption & KMS',
    description: 'Use Data Encryption Key (DEK) pattern for scalable encryption',
    topics: [
      'Envelope encryption concept',
      'Master Key (MK) and Data Encryption Key (DEK)',
      'Key Management Service (KMS)',
      'Minimize master key access',
      'Hierarchical key management'
    ],
    importance: 'Essential for managing encryption at scale',
    pattern: 'Master Key encrypts Data Keys, Data Keys encrypt data'
  };
}

/**
 * Get test status
 * @returns {Object} Test information
 */
function getTest() {
  return {
    status: 'ready',
    tests: ['generateDataKey', 'encryptWithDEK', 'decryptWithDEK'],
    data_keys_generated: Object.keys(keyManagementStore).length,
    encrypted_records: Object.keys(encryptedStore).length
  };
}

/**
 * Generate Data Encryption Key (DEK)
 * @returns {Object} Generated DEK
 */
function generateDataEncryptionKey() {
  try {
    // Generate plaintext DEK
    const plaintextDEK = crypto.randomBytes(32);

    // Encrypt DEK with master key
    const iv = crypto.randomBytes(16);
    const cipher = crypto.createCipheriv('aes-256-cbc', masterKey, iv);
    let encryptedDEK = cipher.update(plaintextDEK, 'utf8', 'hex');
    encryptedDEK += cipher.final('hex');

    const keyId = keyIdCounter++;
    keyManagementStore[keyId] = {
      plaintext_dek: plaintextDEK.toString('hex'),
      encrypted_dek: encryptedDEK,
      iv: iv.toString('hex'),
      algorithm: 'AES-256-CBC',
      created_at: new Date().toISOString(),
      encrypted_by_master_key: true
    };

    return {
      success: true,
      key_id: keyId,
      encrypted_dek: encryptedDEK.substring(0, 32) + '...',
      iv: iv.toString('hex'),
      message: 'Data Encryption Key generated and encrypted with Master Key'
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Encrypt data with DEK
 * @param {string} plaintext - Data to encrypt
 * @param {number} keyId - DEK key ID
 * @returns {Object} Encrypted data
 */
function encryptWithDEK(plaintext, keyId) {
  try {
    if (!keyManagementStore[keyId]) {
      throw new Error(`Data Encryption Key ${keyId} not found`);
    }

    const keyData = keyManagementStore[keyId];

    // Decrypt DEK to use for data encryption
    const decrypted = crypto.createDecipheriv('aes-256-cbc', masterKey, Buffer.from(keyData.iv, 'hex'));
    let dek = decrypted.update(keyData.encrypted_dek, 'hex', 'hex') + decrypted.final('hex');
    const dekBuffer = Buffer.from(dek, 'hex');

    // Encrypt data with DEK
    const dataIv = crypto.randomBytes(16);
    const dataCipher = crypto.createCipheriv('aes-256-cbc', dekBuffer, dataIv);
    let encryptedData = dataCipher.update(plaintext, 'utf8', 'hex');
    encryptedData += dataCipher.final('hex');

    const dataId = dataIdCounter++;
    encryptedStore[dataId] = {
      data: encryptedData,
      iv: dataIv.toString('hex'),
      key_id: keyId,
      algorithm: 'AES-256-CBC',
      encrypted_at: new Date().toISOString()
    };

    return {
      success: true,
      data_id: dataId,
      encrypted_data: encryptedData.substring(0, 32) + '...',
      data_iv: dataIv.toString('hex'),
      key_id: keyId,
      message: 'Data encrypted with Data Encryption Key'
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Decrypt data with DEK
 * @param {number} dataId - Encrypted data ID
 * @returns {Object} Decrypted data
 */
function decryptWithDEK(dataId) {
  try {
    if (!encryptedStore[dataId]) {
      throw new Error(`Encrypted data ${dataId} not found`);
    }

    const dataRecord = encryptedStore[dataId];
    const keyId = dataRecord.key_id;

    if (!keyManagementStore[keyId]) {
      throw new Error(`DEK ${keyId} not found`);
    }

    const keyData = keyManagementStore[keyId];

    // Step 1: Decrypt DEK with master key
    const decrypt1 = crypto.createDecipheriv('aes-256-cbc', masterKey, Buffer.from(keyData.iv, 'hex'));
    let dek = decrypt1.update(keyData.encrypted_dek, 'hex', 'hex') + decrypt1.final('hex');
    const dekBuffer = Buffer.from(dek, 'hex');

    // Step 2: Decrypt data with DEK
    const decrypt2 = crypto.createDecipheriv('aes-256-cbc', dekBuffer, Buffer.from(dataRecord.iv, 'hex'));
    let plaintext = decrypt2.update(dataRecord.data, 'hex', 'utf8');
    plaintext += decrypt2.final('utf8');

    return {
      success: true,
      plaintext,
      key_id: keyId,
      decryption_steps: [
        'Step 1: Master Key decrypts DEK',
        'Step 2: DEK decrypts data'
      ],
      message: 'Data decrypted successfully'
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Demonstrate envelope encryption flow
 * @returns {Object} Flow diagram
 */
function explainEnvelopeEncryption() {
  return {
    concept: 'Envelope Encryption',
    definition: 'Master Key encrypts Data Keys, Data Keys encrypt data',
    flow: {
      step1: 'Application generates random Data Encryption Key (DEK)',
      step2: 'DEK encrypts (wraps) the actual plaintext data',
      step3: 'Master Key encrypts (wraps) the DEK',
      step4: 'Store: encrypted_dek + encrypted_data',
      decrypt_reverse: 'Master Key -> DEK -> data'
    },
    advantages: [
      'Master Key is accessed minimally',
      'Only Master Key needs top-tier security',
      'DEK can be short-lived (rotation friendly)',
      'Scales to millions of encrypted records',
      'Easy to rotate Master Key'
    ],
    use_case: 'AWS KMS, Google Cloud KMS, Azure Key Vault',
    real_world_example: {
      scenario: '1 million records encrypted',
      approach: 'Each record has own DEK, all DEKs encrypted by 1 Master Key',
      benefit: 'Key rotation: reencrypt 1 Master Key instead of 1 million records'
    }
  };
}

/**
 * Rotate Master Key (reencrypt DEKs)
 * @returns {Object} Rotation result
 */
function rotateMasterKey() {
  try {
    const oldMasterKey = masterKey;
    const newMasterKey = crypto.randomBytes(32);

    let reencryptedCount = 0;

    // Reencrypt all DEKs with new master key
    for (const keyId in keyManagementStore) {
      const keyData = keyManagementStore[keyId];

      // Decrypt with old Master Key
      const decrypt = crypto.createDecipheriv('aes-256-cbc', oldMasterKey, Buffer.from(keyData.iv, 'hex'));
      let plainDEK = decrypt.update(keyData.encrypted_dek, 'hex', 'hex') + decrypt.final('hex');

      // Encrypt with new Master Key
      const iv = crypto.randomBytes(16);
      const cipher = crypto.createCipheriv('aes-256-cbc', newMasterKey, iv);
      let newEncrypted = cipher.update(plainDEK, 'hex', 'hex') + cipher.final('hex');

      keyData.encrypted_dek = newEncrypted;
      keyData.iv = iv.toString('hex');
      reencryptedCount++;
    }

    return {
      success: true,
      old_master_key_status: 'Disabled',
      new_master_key_status: 'Active',
      deks_reencrypted: reencryptedCount,
      data_reencryption_needed: false,
      reason: 'Data remains encrypted with same DEKs (DEKs only reencrypted)',
      time_saved: 'Proportional to DEK count (not data volume)'
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Get KMS architecture
 * @returns {Object} Architecture information
 */
function getKMSArchitecture() {
  return {
    master_key: {
      location: 'Hardware Security Module (HSM) / KMS service',
      access_level: 'Strictly limited',
      rotation_frequency: 'Quarterly or on-demand',
      backup: 'Geographically replicated'
    },
    data_encryption_keys: {
      count: 'One per encrypted record',
      lifetime: 'As long as data exists',
      rotation: 'Possible without accessing master key',
      storage: 'Alongside encrypted data (safe because encrypted)'
    },
    benefits: [
      'Never encrypt large volumes directly with Master Key',
      'Master Key secure in HSM/KMS',
      'Data can be encrypted/decrypted client-side',
      'Master Key rotation without re-encrypting all data',
      'Audit trail: see which DEK was used when'
    ]
  };
}

module.exports = {
  getInfo,
  getTest,
  generateDataEncryptionKey,
  encryptWithDEK,
  decryptWithDEK,
  explainEnvelopeEncryption,
  rotateMasterKey,
  getKMSArchitecture
};

