const bcrypt = require('bcrypt');

/**
 * Bcrypt Password Hashing Controller
 * Comprehensive bcrypt implementation and usage
 */

const userDatabase = {};
let userIdCounter = 1;

/**
 * Get module information
 * @returns {Object} Module description
 */
function getInfo() {
  return {
    name: 'Bcrypt Password Hashing',
    description: 'Secure password storage using bcrypt algorithm',
    topics: [
      'Bcrypt algorithm and design',
      'Work factors (rounds)',
      'Cost/performance balance',
      'Adaptive nature of bcrypt',
      'Best practices for password storage'
    ],
    importance: 'Industry standard for password hashing',
    recommended_rounds: 10,
    modern_best_practice_rounds: 11
  };
}

/**
 * Get test status
 * @returns {Object} Test information
 */
function getTest() {
  return {
    status: 'ready',
    tests: ['hashPassword', 'verifyPassword', 'benchmarkRounds'],
    total_users: Object.keys(userDatabase).length
  };
}

/**
 * Hash password using bcrypt
 * @param {string} password - Plain password
 * @param {number} rounds - Work factor (10-12 recommended)
 * @returns {Promise<Object>} Hashing result
 */
async function hashPassword(password, rounds = 11) {
  try {
    if (!password || password.length < 8) {
      throw new Error('Password must be at least 8 characters');
    }

    if (rounds < 4 || rounds > 31) {
      throw new Error('Rounds must be between 4 and 31');
    }

    const startTime = Date.now();
    const hash = await bcrypt.hash(password, rounds);
    const hashTime = Date.now() - startTime;

    return {
      success: true,
      hash,
      rounds,
      hash_time_ms: hashTime,
      algorithm: 'bcrypt',
      security_level: rounds >= 12 ? 'High' : rounds >= 10 ? 'Good' : 'Moderate',
      adaptive_note: 'Time increases as computers get faster, just increase rounds'
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Verify password against bcrypt hash
 * @param {string} password - Plain password attempt
 * @param {string} hash - Bcrypt hash
 * @returns {Promise<Object>} Verification result
 */
async function verifyPassword(password, hash) {
  try {
    const startTime = Date.now();
    const isMatch = await bcrypt.compare(password, hash);
    const verifyTime = Date.now() - startTime;

    return {
      success: true,
      valid: isMatch,
      password_correct: isMatch,
      verify_time_ms: verifyTime,
      timing_safe: 'Yes - time is consistent regardless of match result',
      message: isMatch ? 'Password matches' : 'Password does not match'
    };
  } catch (error) {
    return { success: false, valid: false, error: error.message };
  }
}

/**
 * Register user with bcrypt hashing
 * @param {string} username - Username
 * @param {string} password - Plain password
 * @param {string} email - Email address
 * @returns {Promise<Object>} Registration result
 */
async function registerUser(username, password, email) {
  try {
    if (!username || username.length < 3) {
      throw new Error('Username must be at least 3 characters');
    }
    if (!password || password.length < 8) {
      throw new Error('Password must be at least 8 characters');
    }
    if (!email || !email.includes('@')) {
      throw new Error('Valid email is required');
    }

    // Check if user exists
    const exists = Object.values(userDatabase).some(u => u.username === username);
    if (exists) {
      throw new Error('Username already exists');
    }

    // Hash password with bcrypt
    const hash = await bcrypt.hash(password, 11);

    const userId = userIdCounter++;
    const user = {
      id: userId,
      username,
      email,
      password_hash: hash,
      created_at: new Date().toISOString(),
      last_login: null
    };

    userDatabase[userId] = user;

    return {
      success: true,
      user_id: userId,
      username,
      email,
      message: 'User registered successfully with secure bcrypt password hash'
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Authenticate user with password
 * @param {string} username - Username
 * @param {string} passwordAttempt - Password attempt
 * @returns {Promise<Object>} Authentication result
 */
async function authenticateUser(username, passwordAttempt) {
  try {
    const user = Object.values(userDatabase).find(u => u.username === username);

    if (!user) {
      return {
        success: false,
        authenticated: false,
        message: 'User not found'
      };
    }

    const isValid = await bcrypt.compare(passwordAttempt, user.password_hash);

    if (!isValid) {
      return {
        success: false,
        authenticated: false,
        message: 'Invalid password'
      };
    }

    user.last_login = new Date().toISOString();

    return {
      success: true,
      authenticated: true,
      user_id: user.id,
      username: user.username,
      email: user.email,
      message: 'Authentication successful'
    };
  } catch (error) {
    return { success: false, error: 'Authentication error' };
  }
}

/**
 * Benchmark different round values
 * @returns {Promise<Object>} Benchmark results
 */
async function benchmarkRounds() {
  try {
    const testPassword = 'TestPassword123';
    const rounds = [8, 10, 11, 12, 13];
    const results = [];

    for (const round of rounds) {
      const startTime = Date.now();
      await bcrypt.hash(testPassword, round);
      const elapsed = Date.now() - startTime;

      results.push({
        rounds: round,
        hash_time_ms: elapsed,
        security_level: round >= 12 ? 'High' : round >= 10 ? 'Good' : 'Moderate',
        recommendation: round === 11 ? 'RECOMMENDED' : ''
      });
    }

    return {
      success: true,
      benchmark_results: results,
      recommended_rounds: 11,
      note: 'Higher rounds = slower hashing = better security against brute force'
    };
  } catch (error) {
    return { error: error.message };
  }
}

/**
 * Explain bcrypt strength
 * @returns {Object} Explanation
 */
function explainBcryptStrength() {
  return {
    why_bcrypt_is_secure: [
      'Salted: random salt generated for each password',
      'Adaptive: work factor increases over time as computers get faster',
      'Slow: intentionally slow hashing (unlike SHA256)',
      'Proven: designed by password security expert'
    ],
    work_factor_meaning: {
      4: 'Too fast (for 2024+)',
      8: 'Weak by 2024 standards',
      10: 'Acceptable minimum',
      11: 'Recommended (good balance)',
      12: 'High security (slower)',
      13: 'Very high (considerably slower)'
    },
    comparison_with_plaintext_hash: {
      sha256_plaintext: {
        time_to_crack_1_billion_passwords: '2 seconds',
        security_level: 'NONE'
      },
      bcrypt_rounds_11: {
        time_per_hash: '300ms',
        time_to_crack_1_billion: 'Billions of years',
        security_level: 'EXCELLENT'
      }
    },
    password_strength: 'Even weak passwords are protected by bcrypt\'s slowness'
  };
}

/**
 * Rehash password if rounds increased
 * @param {number} userId - User ID
 * @param {string} password - Current password to verify
 * @param {number} newRounds - New rounds value
 * @returns {Promise<Object>} Rehashing result
 */
async function rehashPassword(userId, password, newRounds = 12) {
  try {
    if (!userDatabase[userId]) {
      throw new Error(`User ${userId} not found`);
    }

    const user = userDatabase[userId];

    // Verify current password
    const isValid = await bcrypt.compare(password, user.password_hash);
    if (!isValid) {
      throw new Error('Current password is incorrect');
    }

    // Hash with new rounds
    const newHash = await bcrypt.hash(password, newRounds);
    user.password_hash = newHash;

    return {
      success: true,
      user_id: userId,
      rehashed: true,
      new_rounds: newRounds,
      message: 'Password rehashed with new work factor'
    };
  } catch (error) {
    return { error: error.message };
  }
}

module.exports = {
  getInfo,
  getTest,
  hashPassword,
  verifyPassword,
  registerUser,
  authenticateUser,
  benchmarkRounds,
  explainBcryptStrength,
  rehashPassword
};
